window.PLACE_CONTENT={"places":[{"id":"luxembourg","name":{"en":"Luxembourg Gardens","he":"גני לוקסמבורג"},"shortIntro":{"en":"The old nursery and the changing paths of Luxembourg.","he":"המשתלה הישנה והשבילים המשתנים של גני לוקסמבורג."},"region":{"en":"Paris · 6th arrondissement","he":"פריז · הרובע השישי"},"status":"surviving-changed","statusLabel":{"en":"Surviving garden · altered layout","he":"גן קיים · התכנון השתנה"},"coordinates":[48.846944,2.336944],"coordinatePrecision":"garden reference point; not the fictional bench","coordinateSource":"https://fr.wikipedia.org/wiki/Jardin_du_Luxembourg","mapNote":{"en":"The pin marks Luxembourg Gardens. Their layout has changed since the novel’s period.","he":"הסמן מציין את גני לוקסמבורג. תכנון הגן השתנה מאז תקופת העלילה."},"legacyMapId":"luxembourg","novelPart":3,"spoilerLevel":"premise","history":{"en":"Luxembourg Gardens began with Marie de’ Medici’s palace project in the early seventeenth century. The French Senate’s history records successive changes to the grounds, including those of the Haussmann era. Hugo locates his walkers by the old nursery and Rue de l’Ouest. Those names describe an earlier layout; the present-day photograph shows the garden after generations of rebuilding.","he":"גני לוקסמבורג החלו במפעל הארמון של מארי דה מדיצ׳י בראשית המאה השבע־עשרה. תולדות הגן שמפרסם הסנאט הצרפתי מתעדות שינויים חוזרים בשטחו, ובהם העבודות בתקופת אוסמן. הוגו ממקם את המטיילים בעזרת המשתלה הישנה ורחוב דה לואסט. השמות האלה שייכים לתכנון מוקדם יותר; התצלום בן זמננו מציג את הגן אחרי דורות של שינויים."},"novel":{"en":"Marius first knows the pair on the bench as Monsieur Leblanc and Mademoiselle Lanoire, nicknames borrowed from the students. For months he barely notices the girl. When he falls in love with Cosette, the same walk becomes an elaborate performance: new clothes, repeated passes and an effort to appear unconcerned. Hugo lets us see the preparation behind that supposed accident. Valjean, meanwhile, has reason to watch the young man watching his daughter. The garden gives all three a reason to be there without requiring them to speak.","he":"מריוס מכיר תחילה את הצמד שעל הספסל כ״מר לבן״ ו״העלמה שחורה״, כינויים שקיבל מן הסטודנטים. במשך חודשים הוא כמעט אינו מבחין בנערה. כשהוא מתאהב בקוזט, אותו טיול נעשה מבצע מתוכנן: בגדים חדשים, מעברים חוזרים וניסיון להיראות אדיש. הוגו מראה את ההכנות שמאחורי המפגש המקרי לכאורה. ולז׳אן, בינתיים, מתחיל לשים לב לצעיר שמביט בבתו. הגן מאפשר לשלושתם להימצא באותו מקום בלי שיצטרכו לדבר."},"novelRefs":[{"label":{"en":"III · VI · 1–5","he":"חלק III · ספר VI · פרקים 1–5"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2HCH0188"}],"historySources":[{"label":{"en":"French Senate · Garden history","he":"הסנאט הצרפתי · תולדות הגן"},"url":"https://jardin.senat.fr/en/history-heritage.html"},{"label":{"en":"French Senate · Palace origins","he":"הסנאט הצרפתי · ראשיתו של הארמון"},"url":"https://www.senat.fr/connaitre-le-senat/lhistoire-du-senat/les-collections-precieuses-de-la-bibliotheque-du-senat-le-palais-du-luxembourg.html"}],"precisionLabel":{"en":"Surviving garden · altered layout","he":"גן קיים · התכנון השתנה"},"photo":{"src":"/assets/places/luxembourg.webp","sourceUrl":"https://commons.wikimedia.org/wiki/File:Paris_75006_Jardin_du_Luxembourg_Bassin_20170527.jpg","author":"xiquinhosilva","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0/","title":"Paris 75006 Jardin du Luxembourg Bassin 20170527.jpg","caption":{"en":"The Luxembourg Gardens in 2017, looking toward the Panthéon. A present-day view of a garden named in the novel.","he":"גני לוקסמבורג בשנת 2017, במבט לעבר הפנתאון. מבט בן זמננו על גן המוזכר ברומן."},"alt":{"en":"Green chairs, palms and garden terraces at the Luxembourg Gardens, with the Panthéon in the distance.","he":"כיסאות ירוקים, דקלים וטרסות בגני לוקסמבורג, והפנתאון ברקע."},"width":1600,"height":1068,"modified":true,"transformations":{"he":"הפריים המלא נשמר. התמונה הוקטנה והומרה ל־WebP; ללא חיתוך, צביעה או עריכת התוכן.","en":"Whole frame retained; resized and converted to WebP for web delivery. No content editing, colorization, reconstruction, retouching, or cropping."}}},{"id":"rue-plumet","name":{"en":"Rue Plumet, now Rue Oudinot","he":"רחוב פלומה, כיום רחוב אודינו"},"shortIntro":{"en":"Look for Rue Oudinot on today’s map.","he":"במפה של היום חפשו את רחוב אודינו."},"region":{"en":"Paris · 7th arrondissement","he":"פריז · הרובע השביעי"},"status":"renamed","statusLabel":{"en":"Historic street · renamed","he":"רחוב היסטורי · שמו השתנה"},"coordinates":[48.85011,2.3175],"coordinatePrecision":"street reference point; no fictional house identified","coordinateSource":"https://fr.wikipedia.org/wiki/Rue_Oudinot","mapNote":{"en":"Hugo’s Rue Plumet is today’s Rue Oudinot in the seventh arrondissement. The modern Rue Plumet lies in the fifteenth. Valjean and Cosette’s house and garden belong to the novel.","he":"רחוב פלומה של הוגו נקרא כיום רחוב אודינו, ברובע השביעי. רחוב פלומה הנוכחי נמצא ברובע ה־15. הבית והגן של ולז׳אן וקוזט הם חלק מן הרומן."},"legacyMapId":"plumet","novelPart":4,"spoilerLevel":"plot","history":{"en":"Hugo’s Rue Plumet is now Rue Oudinot in the seventh arrondissement. Today’s Rue Plumet lies in the fifteenth, so searching the novel’s street name can lead to the wrong neighborhood. Municipal heritage records document the older name. The photograph shows Rue Oudinot as it survives; the secluded pavilion, overgrown garden and secret passage belong to Hugo’s account of the house.","he":"רחוב פלומה של הוגו נקרא כיום רחוב אודינו, ברובע השביעי. הרחוב שנושא היום את השם פלומה נמצא ברובע ה־15, ולכן חיפוש לפי השם שברומן עלול להוביל לשכונה הלא נכונה. מסמכי המורשת העירוניים מתעדים את השם הקודם. התצלום מציג את רחוב אודינו ששרד; הביתן המבודד, הגן הפראי והמעבר הסודי שייכים לתיאור הבית אצל הוגו."},"novel":{"en":"Valjean rents the house under the name Fauchelevent and repairs the concealed exits of a passage leading to Rue de Babylone. Cosette occupies the furnished pavilion; he chooses the smaller lodging behind it. The arrangement makes his habits visible: comfort for her, few possessions for himself, and a way out if they are discovered. Hugo then devotes a chapter to the untended garden, where plants spread across the old boundaries. The house is planned around hiding; Cosette’s growing interest in the world outside makes that plan harder to maintain.","he":"ולז׳אן שוכר את הבית בשם פושלוון ומתקן את פתחי המעבר הנסתר המוליך לרחוב בבלון. קוזט מתגוררת בביתן המרוהט; הוא בוחר במגורים הקטנים שמאחוריו. הסידור חושף את הרגליו: נוחות עבורה, מעט חפצים לעצמו ודרך מילוט למקרה שיתגלו. הוגו מקדיש אחר כך פרק לגן המוזנח, שהצמחים בו מתפשטים מעבר לגבולות הישנים. הבית מתוכנן סביב הצורך להסתתר; העניין הגובר של קוזט בעולם שבחוץ מקשה לשמור על הסדר הזה."},"novelRefs":[{"label":{"en":"IV · III · 1–3","he":"חלק IV · ספר III · פרקים 1–3"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2HCH0233"},{"label":{"en":"IV · III · 3: Foliis ac frondibus","he":"חלק IV · ספר III · פרק 3: Foliis ac frondibus"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2HCH0235"}],"historySources":[{"label":{"en":"Commission du Vieux Paris · 6 March 2012","he":"ועדת פריז העתיקה · 6 במרץ 2012"},"url":"https://cdn.paris.fr/paris/2020/09/30/969a917f8a1c831bc945d48ce73bcd4f.pdf"}],"precisionLabel":{"en":"Historic street · renamed","he":"רחוב היסטורי · שמו השתנה"},"photo":{"src":"/assets/places/rue-plumet.webp","sourceUrl":"https://commons.wikimedia.org/wiki/File:Paris_rue_oudinot2.jpg","author":"Ralf.treinen","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/","title":"Paris rue oudinot2.jpg","caption":{"en":"Rue Oudinot in 2012, photographed eastward from Rue Monsieur: the historical Rue Plumet.","he":"רחוב אודינו בשנת 2012, במבט מזרחה מרחוב מסייה. זהו רחוב פלומה ההיסטורי."},"alt":{"en":"A narrow Paris street lined with pale façades, shutters and parked cars.","he":"רחוב פריזאי צר, חזיתות בהירות, תריסים ומכוניות חונות."},"width":1600,"height":1200,"modified":true,"transformations":{"he":"הפריים המלא נשמר. התמונה הוקטנה והומרה ל־WebP; ללא חיתוך, צביעה או עריכת התוכן.","en":"Whole frame retained; resized and converted to WebP for web delivery. No content editing, colorization, reconstruction, retouching, or cropping."}}},{"id":"chanvrerie","name":{"en":"Rue de la Chanvrerie","he":"רחוב לה שאנבררי"},"shortIntro":{"en":"A vanished street beside today’s Rue Mondétour.","he":"רחוב שנעלם, ליד רחוב מונדטור של היום."},"region":{"en":"Paris · Les Halles","he":"פריז · לה האל"},"status":"lost-street","statusLabel":{"en":"Lost street · approximate area","he":"רחוב שנעלם · אזור משוער"},"coordinates":[48.8627,2.347925],"coordinatePrecision":"nearby surviving Rue Mondétour reference point; approximate historical area","coordinateSource":"https://fr.wikipedia.org/wiki/Rue_Mond%C3%A9tour","mapNote":{"en":"The pin marks the Rue Mondétour/Rue Rambuteau area, near the vanished Rue de la Chanvrerie, where Hugo places Corinthe and the barricade.","he":"הסמן מציין את אזור רחובות מונדטור ורמבוטו, סמוך לרחוב שאנבררי שנעלם. כאן מציב הוגו את קורינת ואת המתרס."},"legacyMapId":"chanvrerie","novelPart":4,"spoilerLevel":"plot","history":{"en":"Rue de la Chanvrerie disappeared in the rebuilding around Rue Rambuteau. Hugo begins the Corinthe episode by asking his own readers to reconstruct a street they could no longer see intact. Municipal research at 102 Rue Rambuteau records surviving fabric from the older neighborhood. The photograph shows nearby Rue Mondétour today; Hugo’s street description supplies the narrow turns and enclosed approaches of the barricade site.","he":"רחוב לה שאנבררי נעלם בבנייה מחדש סביב רחוב רמבוטו. הוגו פותח את פרשת קורינת בבקשה מקוראיו לדמיין מחדש רחוב שגם הם כבר לא יכלו לראות בשלמותו. מחקר עירוני ברמבוטו 102 מתעד שרידים מן המרקם הישן. התצלום מציג את רחוב מונדטור הסמוך כיום; תיאור הרחובות ברומן משלים את הפניות הצרות ואת דרכי הגישה התחומות אל המתרס."},"novel":{"en":"Hugo introduces Corinthe as a working tavern, with meals, regular customers and arguments, before the insurgents turn it into a stronghold. Tables and other furniture leave their ordinary uses and become barricade material. The narrow approaches decide where the defenders can see and where attackers can come from. This is the fictional company’s position during the real June uprising of 1832. Keeping the tavern in mind matters: the fighting takes over a place where people had been earning a living and sitting down to eat.","he":"הוגו מציג את קורינת כבית מרזח פעיל, עם ארוחות, לקוחות קבועים וויכוחים, לפני שהמורדים הופכים אותו למעוז. שולחנות ורהיטים אחרים יוצאים משימושם הרגיל ונעשים חומרי בנייה למתרס. דרכי הגישה הצרות קובעות מה יוכלו המגינים לראות ומאין יוכלו התוקפים להגיע. זו העמדה של חבורת הדמויות הבדיונית במרד יוני האמיתי של 1832. כדאי לזכור את בית המרזח שקדם לה: הלחימה משתלטת על מקום שבו אנשים התפרנסו וישבו לאכול."},"novelRefs":[{"label":{"en":"IV · XII · 1","he":"חלק IV · ספר XII · פרק 1"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2HCH0277"},{"label":{"en":"IV · XII · 4–5","he":"חלק IV · ספר XII · פרקים 4–5"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2HCH0280"}],"historySources":[{"label":{"en":"Commission du Vieux Paris · 19 October 2017, pp. 32–33","he":"ועדת פריז העתיקה · 19 באוקטובר 2017, עמ׳ 32–33"},"url":"https://cdn.paris.fr/paris/2019/07/24/93bb6132691fdd80e007396945d2a1e0.pdf"}],"precisionLabel":{"en":"Lost street · approximate area","he":"רחוב שנעלם · אזור משוער"},"photo":{"src":"/assets/places/chanvrerie.webp","sourceUrl":"https://commons.wikimedia.org/wiki/File:Rue_Mond%C3%A9tour_-_Paris_I_(FR75)_-_2021-06-05_-_1.jpg","author":"Chabe01","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","title":"Rue Mondétour - Paris I (FR75) - 2021-06-05 - 1.jpg","caption":{"en":"Rue Mondétour in 2021, near the vanished Rue de la Chanvrerie.","he":"רחוב מונדטור בשנת 2021, בסביבת רחוב שאנבררי שנעלם."},"alt":{"en":"A pedestrian street with café terraces on Rue Mondétour in present-day Paris.","he":"רחוב להולכי רגל עם שולחנות בתי קפה ברחוב מונדטור בפריז של ימינו."},"width":1600,"height":1200,"modified":true,"transformations":{"he":"הפריים המלא נשמר. התמונה הוקטנה והומרה ל־WebP; ללא חיתוך, צביעה או עריכת התוכן.","en":"Whole frame retained; resized and converted to WebP for web delivery. No content editing, colorization, reconstruction, retouching, or cropping."}}},{"id":"bastille","name":{"en":"Place de la Bastille & the lost elephant","he":"כיכר הבסטיליה והפיל שנעלם"},"shortIntro":{"en":"Napoleon’s elephant, built in plaster and later demolished.","he":"הפיל של נפוליאון, שנבנה בגבס ובהמשך נהרס."},"region":{"en":"Paris · Bastille","he":"פריז · הבסטיליה"},"status":"lost-monument","statusLabel":{"en":"Square survives · elephant demolished","he":"הכיכר קיימת · הפיל נהרס"},"coordinates":[48.853092,2.369563],"coordinatePrecision":"modern square reference point; not the elephant footprint","coordinateSource":"https://fr.wikipedia.org/wiki/Place_de_la_Bastille","mapNote":{"he":"זו נקודת ייחוס לכיכר של ימינו. הפיל אינו קיים עוד; לצד התצלום אפשר לפתוח גם תכנון אדריכלי משנת 1814.","en":"This is a reference point for the present-day square. The elephant is gone; the essay also includes an architectural design from 1814."},"legacyMapId":null,"novelPart":4,"spoilerLevel":"plot","history":{"en":"Napoleon planned a bronze elephant fountain for the Bastille. Only the full-size plaster model was built; it stood in the square, deteriorating, until its removal in 1846. The July Column in the main photograph was inaugurated in 1840 to commemorate the dead of the July Revolution of 1830. The historical design in the second image records the elephant project. Neither image shows the square exactly as it was during the novel’s 1832 uprising.","he":"נפוליאון תכנן בכיכר הבסטיליה מזרקת פיל מברונזה. רק דגם הגבס בגודל מלא נבנה; הוא עמד בכיכר והלך והתבלה עד שסולק ב־1846. עמוד יולי שבתצלום הראשי נחנך ב־1840 לזכר ההרוגים במהפכת יולי 1830. התכנון ההיסטורי בתמונה הנוספת מתעד את מיזם הפיל. אף אחת מהתמונות אינה מציגה את הכיכר בדיוק כפי שנראתה בזמן ההתקוממות של 1832 ברומן."},"novel":{"en":"Gavroche takes a ladder, helps two lost boys through a hole in the elephant’s belly and closes the entrance with a plank. Inside, he has improvised a bed and protection against the rats. His jokes about his grand residence help him settle the frightened children, although the shelter is cold, dark and verminous. Hugo pauses to ask what the abandoned monument is good for and answers with these three children asleep inside it. The elephant’s practical use is measured in the night’s shelter Gavroche can share.","he":"גברוש לוקח סולם, עוזר לשני ילדים אבודים להיכנס דרך חור בבטן הפיל וסוגר את הכניסה בקרש. בפנים הכין מיטה מאולתרת והגנה מפני החולדות. הבדיחות שלו על מעונו המפואר עוזרות להרגיע את הילדים המבוהלים, אף שהמחסה קר, חשוך ושורץ מזיקים. הוגו עוצר לשאול מה התועלת באנדרטה הנטושה, ומשיב בתיאור שלושת הילדים הישנים בתוכה. התועלת המעשית של הפיל נמדדת בלילה של מחסה שגברוש יכול לחלוק."},"novelRefs":[{"label":{"en":"IV · VI · 2","he":"חלק IV · ספר VI · פרק 2"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2HCH0250"}],"historySources":[{"label":{"en":"Fondation Napoléon · The Bastille elephant","he":"קרן נפוליאון · הפיל של הבסטיליה"},"url":"https://www.napoleon.org/jeunes-historiens/napodoc/monuments-napoleoniens-le-mysterieux-elephant-de-la-place-de-la-bastille"},{"label":{"en":"Centre des monuments nationaux · July Column history","he":"המרכז למונומנטים לאומיים · תולדות עמוד יולי"},"url":"https://www.colonne-de-juillet.fr/decouvrir/histoire-de-la-colonne-de-juillet"}],"precisionLabel":{"en":"Square survives · elephant demolished","he":"הכיכר קיימת · הפיל נהרס"},"photo":{"src":"/assets/places/bastille-modern.webp","sourceUrl":"https://commons.wikimedia.org/wiki/File:Place_de_la_Bastille%2C_avril_2021.jpg","author":"Guillaume Flament","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","title":"Place de la Bastille, avril 2021.jpg","caption":{"en":"Place de la Bastille in April 2021, with the July Column.","he":"כיכר הבסטיליה באפריל 2021, עם עמוד יולי."},"alt":{"en":"The July Column rises above the broad paved Place de la Bastille, framed by trees and Parisian buildings.","he":"עמוד יולי מעל הרחבה המרוצפת של כיכר הבסטיליה, בין עצים ובניינים פריזאיים."},"width":1600,"height":1067,"modified":true,"transformations":{"he":"הפריים המלא נשמר. התמונה הוקטנה והומרה ל־WebP; ללא חיתוך, צביעה או עריכת התוכן.","en":"Whole frame retained; resized and converted to WebP for web delivery. No content editing, colorization, reconstruction, retouching, or cropping."}},"secondaryPhoto":{"src":"/assets/places/bastille.webp","sourceUrl":"https://commons.wikimedia.org/wiki/File:La_fontaine_de_l'%C3%A9l%C3%A9phant%2C_place_de_la_Bastille%2C_D.8274(2).jpg","author":"Jean-Antoine Alavoine","license":"CC0 1.0","licenseUrl":"https://creativecommons.org/publicdomain/zero/1.0/","title":"La fontaine de l'éléphant, place de la Bastille, D.8274(2).jpg","caption":{"en":"Jean-Antoine Alavoine’s 1814 architectural watercolor for the elephant fountain at the Bastille.","he":"תכנון מזרקת הפיל בבסטיליה: צבעי מים מאת ז׳אן־אנטואן אלאבואן, 1814."},"alt":{"en":"A period watercolor of a monumental elephant fountain with a howdah, basin, pedestrians and canal boats.","he":"ציור תקופתי של מזרקה בצורת פיל עצום, עם אפריון, בריכה, הולכי רגל וסירות בתעלה."},"width":1600,"height":1182,"modified":true,"transformations":{"he":"הפריים המלא נשמר. התמונה הוקטנה והומרה ל־WebP; ללא חיתוך, צביעה או עריכת התוכן.","en":"Whole frame retained; resized and converted to WebP for web delivery. No content editing, colorization, reconstruction, retouching, or cropping."}}},{"id":"pont-au-change","name":{"en":"Pont au Change & the Seine","he":"גשר או שאנז׳ והסיין"},"shortIntro":{"en":"Pont au Change is the landmark; Pont Notre-Dame locates the scene.","he":"גשר או שאנז׳ מסייע להתמצא; גשר נוטרדאם ממקם את הסצנה."},"region":{"en":"Paris · Île de la Cité","he":"פריז · איל דה לה סיטה"},"status":"rebuilt","statusLabel":{"en":"Bridge rebuilt · narrative area nearby","he":"הגשר נבנה מחדש · אזור העלילה סמוך"},"coordinates":[48.856667,2.346667],"coordinatePrecision":"present bridge reference point; not an exact narrative event location","coordinateSource":"https://fr.wikipedia.org/wiki/Pont_au_Change","mapNote":{"en":"The pin marks today’s Pont au Change, rebuilt in 1860. Hugo places Javert’s scene on the quay at the corner of nearby Pont Notre-Dame.","he":"הסמן מציין את גשר או שאנז׳ הנוכחי, שנבנה מחדש ב־1860. סצנת ז׳אבר מתרחשת ברומן על הרציף בפינת גשר נוטרדאם הסמוך."},"legacyMapId":null,"novelPart":5,"spoilerLevel":"major","history":{"en":"Pont au Change links the right bank with Île de la Cité. The city records its reconstruction in 1860, after the novel’s main action. Hugo describes the stretch of river between this bridge and nearby Pont Notre-Dame. The photograph, with the Conciergerie beside the bridge, helps locate that stretch of the Seine in the rebuilt city.","he":"גשר או שאנז׳ מחבר את הגדה הימנית עם איל דה לה סיטה. העירייה מתעדת את בנייתו מחדש ב־1860, לאחר תקופת העלילה המרכזית. הוגו מתאר את קטע הנהר שבין הגשר הזה לבין גשר נוטרדאם הסמוך. התצלום, ובו הקונסיירז׳רי לצד הגשר, מסייע לאתר את הקטע הזה של הסיין בעיר שנבנתה מחדש."},"novel":{"en":"After releasing Valjean, Javert walks to the quay at the corner of Pont Notre-Dame. He has acted against the rules he enforced throughout his career, and returning to arrest Valjean would mean betraying the man who spared him. Before his death in the Seine, he writes a list of recommendations for the police, including a complaint about prisoners made to stand barefoot during searches. Even this final chapter keeps the inspector’s administrative habits in view. Pont au Change describes the neighboring river reach; Hugo places Javert’s last scene beside Pont Notre-Dame.","he":"אחרי ששחרר את ולז׳אן, ז׳אבר הולך לרציף שבפינת גשר נוטרדאם. הוא פעל בניגוד לכללים שאכף לאורך חייו, וחזרה כדי לעצור את ולז׳אן תהיה בגידה באדם שחס עליו. לפני מותו בסיין הוא כותב רשימת המלצות למשטרה, ובה תלונה על אסירים הנאלצים לעמוד יחפים בזמן חיפוש. גם הפרק האחרון שלו שומר על הרגלי העבודה של המפקח. גשר או שאנז׳ משמש לתיאור קטע הנהר הסמוך; הוגו ממקם את הסצנה האחרונה של ז׳אבר לצד גשר נוטרדאם."},"novelRefs":[{"label":{"en":"V · IV · 1","he":"חלק V · ספר IV · פרק 1"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2HCH0341"}],"historySources":[{"label":{"en":"Ville de Paris · History of the Seine banks","he":"עיריית פריז · תולדות גדות הסיין"},"url":"https://www.paris.fr/webdocs/rives-de-seine/revivre"},{"label":{"en":"Musée Carnavalet · Reconstruction, 1856–1860","he":"מוזיאון קרנוולה · הבנייה מחדש, 1856–1860"},"url":"https://www.parismuseescollections.paris.fr/en/node/84528"}],"precisionLabel":{"en":"Bridge rebuilt · narrative area nearby","he":"הגשר נבנה מחדש · אזור העלילה סמוך"},"photo":{"src":"/assets/places/pont-au-change.webp","sourceUrl":"https://commons.wikimedia.org/wiki/File:Pont_au_Change_and_Conciergerie%2C_Paris_2_April_2014.jpg","author":"DXR","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","title":"Pont au Change and Conciergerie, Paris 2 April 2014.jpg","caption":{"en":"Pont au Change and the Conciergerie in 2014. The present bridge was built in 1860, after the novel’s period.","he":"גשר או שאנז׳ והקונסיירז׳רי בשנת 2014. הגשר הנוכחי נבנה ב־1860, לאחר תקופת העלילה."},"alt":{"en":"Pont au Change crossing the Seine beside the Conciergerie, viewed from Pont Neuf.","he":"פון־או־שאנז׳ חוצה את הסן לצד הקונסיירז׳רי, במבט מפון נף."},"width":1600,"height":900,"modified":true,"transformations":{"he":"הפריים המלא נשמר. התמונה הוקטנה והומרה ל־WebP; ללא חיתוך, צביעה או עריכת התוכן.","en":"Whole frame retained; resized and converted to WebP for web delivery. No content editing, colorization, reconstruction, retouching, or cropping."}}},{"id":"saint-paul-saint-louis","name":{"en":"Saint-Paul-Saint-Louis","he":"כנסיית סן־פול־סן־לואי"},"shortIntro":{"en":"A seventeenth-century church on Rue Saint-Antoine.","he":"כנסייה מן המאה השבע־עשרה ברחוב סן־אנטואן."},"region":{"en":"Paris · Le Marais","he":"פריז · המארה"},"status":"surviving-landmark","statusLabel":{"en":"Surviving church","he":"כנסייה קיימת"},"coordinates":[48.854722,2.361389],"coordinatePrecision":"surviving church location","coordinateSource":"https://fr.wikipedia.org/wiki/%C3%89glise_Saint-Paul-Saint-Louis","mapNote":{"en":"The pin marks the surviving church on Rue Saint-Antoine. Hugo calls it Saint-Paul and identifies its Jesuit origins.","he":"הסמן מציין את הכנסייה הקיימת ברחוב סן־אנטואן. הוגו קורא לה סן־פול ומציין את מקורה הישועי."},"legacyMapId":null,"novelPart":5,"spoilerLevel":"major","history":{"en":"Saint-Paul-Saint-Louis stands on Rue Saint-Antoine in the Marais. Municipal heritage records trace the Jesuit church’s construction from 1627 and identify the architects Étienne Martellange and François Derand. Hugo calls it Saint-Paul and explicitly mentions its Jesuit origins. The surviving church is still an active parish; the photograph records its façade in 2023.","he":"כנסיית סן־פול־סן־לואי ניצבת ברחוב סן־אנטואן במארה. תיעוד המורשת העירוני עוקב אחר בניית הכנסייה הישועית החל ב־1627 ומציין את האדריכלים אטיין מרטלנז׳ ופרנסואה דראן. הוגו קורא לה סן־פול ומזכיר במפורש את מקורה הישועי. הכנסייה ששרדה משמשת גם כיום קהילה פעילה; התצלום מתעד את חזיתה בשנת 2023."},"novel":{"en":"Marius and Cosette marry on 16 February 1833. Gillenormand arranges for the wedding to take place at Saint-Paul, which he prefers to their own parish church. Hugo follows the carriages through carnival traffic rather than describing the ceremony itself. Valjean arrives with his right hand bandaged and cannot sign; Gillenormand signs in his place as Cosette’s supervising guardian. Amid the wedding preparations, that small legal substitution begins to expose Valjean’s difficulty: he has raised Cosette, but his borrowed name cannot safely explain who he is.","he":"מריוס וקוזט נישאים ב־16 בפברואר 1833. ז׳ילנורמן מסדיר את עריכת החתונה בסן־פול, שאותה הוא מעדיף על כנסיית הקהילה שלהם. הוגו מלווה את הכרכרות בתנועת הקרנבל ואינו מתאר את הטקס עצמו. ולז׳אן מגיע כשידו הימנית חבושה ואינו יכול לחתום; ז׳ילנורמן חותם במקומו כאפוטרופוס המפקח של קוזט. בתוך ההכנות לחתונה, ההחלפה המשפטית הקטנה הזאת מתחילה לחשוף את הקושי של ולז׳אן: הוא גידל את קוזט, אך השם השאול שלו אינו מאפשר לו להסביר בבטחה מיהו."},"novelRefs":[{"label":{"en":"V · V · 4","he":"חלק V · ספר V · פרק 4"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2HCH0345"},{"label":{"en":"V · VI · 1–2","he":"חלק V · ספר VI · פרקים 1–2"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2HCH0350"}],"historySources":[{"label":{"en":"Ville de Paris · Marais heritage report, p. 37","he":"עיריית פריז · דו״ח מורשת המארה, עמ׳ 37"},"url":"https://cdn.paris.fr/paris/2020/02/26/ca8ea055b185b2c2098f53e5204c2eba.pdf"},{"label":{"en":"Saint-Paul-Saint-Louis · Official parish","he":"סן־פול־סן־לואי · אתר הקהילה הרשמי"},"url":"https://www.spsl.fr/"}],"precisionLabel":{"en":"Surviving church","he":"כנסייה קיימת"},"photo":{"src":"/assets/places/saint-paul-saint-louis.webp","sourceUrl":"https://commons.wikimedia.org/wiki/File:Paris_Saint-Paul-Saint-Louis_2023-04-04.jpg","author":"Drycker","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","title":"Paris Saint-Paul-Saint-Louis 2023-04-04.jpg","caption":{"en":"The façade of Saint-Paul-Saint-Louis in 2023. The church is a surviving location explicitly named in the novel; this photograph shows its present-day appearance.","he":"חזית כנסיית סן־פול־סן־לואי בשנת 2023. הכנסייה היא מקום קיים הנקוב במפורש ברומן; התצלום מציג את מראהּ בן זמננו."},"alt":{"en":"The pale stone Baroque façade and red doors of Saint-Paul-Saint-Louis beneath a blue sky.","he":"חזית האבן הבארוקית הבהירה ודלתותיה האדומות של כנסיית סן־פול־סן־לואי תחת שמיים כחולים."},"width":1280,"height":1706,"modified":true,"transformations":{"he":"הפריים המלא נשמר. התמונה הוקטנה והומרה ל־WebP; ללא חיתוך, צביעה או עריכת התוכן.","en":"Whole frame retained; resized and converted to WebP for web delivery. No content editing, colorization, reconstruction, retouching, or cropping."}}},{"id":"pont-austerlitz","name":{"en":"Pont d’Austerlitz","he":"גשר אוסטרליץ"},"shortIntro":{"en":"A river crossing rebuilt in 1854.","he":"מעבר על הנהר שנבנה מחדש ב־1854."},"region":{"en":"Paris · Jardin des Plantes / Arsenal","he":"פריז · ז׳רדן דה פלאנט / ארסנל"},"status":"rebuilt","statusLabel":{"en":"Historic crossing · rebuilt bridge","he":"מעבר היסטורי · הגשר נבנה מחדש"},"coordinates":[48.845,2.366111],"coordinatePrecision":"present bridge reference point; earlier bridge rebuilt in 1854","coordinateSource":"https://fr.wikipedia.org/wiki/Pont_d%27Austerlitz","mapNote":{"en":"The river crossing is real. The current masonry bridge dates from a rebuilding in 1854, after the novel’s main period.","he":"המעבר מעל הנהר אמיתי. גשר האבן הנוכחי נבנה מחדש ב־1854, לאחר התקופה המרכזית המתוארת ברומן."},"legacyMapId":null,"novelPart":2,"spoilerLevel":"plot","history":{"en":"Pont d’Austerlitz crosses the Seine near the Jardin des Plantes and the Arsenal side of the city. A medal in the Musée Carnavalet commemorates its reconstruction in November 1854, decades after the escape Hugo sets here. The crossing remains a useful landmark for following that route. The stone arches in the photograph belong to the later bridge.","he":"גשר אוסטרליץ חוצה את הסיין סמוך לז׳רדן דה פלאנט ומול אזור הארסנל. מדליה באוסף מוזיאון קרנוולה מנציחה את בנייתו מחדש בנובמבר 1854, עשרות שנים אחרי המנוסה שהוגו ממקם כאן. המעבר נשאר נקודת ציון מועילה למעקב אחר הדרך הזאת. קשתות האבן שבתצלום שייכות לגשר המאוחר יותר."},"novel":{"en":"Valjean reaches the bridge carrying the tired Cosette and offers one sou at the toll booth. The collector demands two: a child who can walk must pay. Valjean pays, annoyed that anyone has noticed them. A heavy cart gives them cover across the moonlit bridge, but the open ground beyond exposes them again. When he looks back, four men are entering the crossing. Hugo builds the pursuit from these practical details: the fare, the cart’s shadow and the few yards they must cross in full view.","he":"ולז׳אן מגיע לגשר כשקוזט העייפה בזרועותיו ומושיט סו אחד בעמדת האגרה. הגובה דורש שניים: גם ילד המסוגל ללכת חייב לשלם. ולז׳אן משלם, מוטרד מכך שמישהו הבחין בהם. עגלה כבדה מסתירה אותם בזמן חציית הגשר המואר באור הירח, אבל השטח הפתוח שמעבר לו חושף אותם מחדש. כשהוא מביט לאחור, ארבעה גברים נכנסים אל הגשר. הוגו בונה את המרדף מן הפרטים המעשיים האלה: התשלום, צל העגלה והמרחק הקצר שצריך לעבור לעיני כול."},"novelRefs":[{"label":{"en":"II · V · 2","he":"חלק II · ספר V · פרק 2"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2HCH0110"}],"historySources":[{"label":{"en":"Musée Carnavalet · Reconstruction medal, 1854","he":"מוזיאון קרנוולה · מדליית הבנייה מחדש, 1854"},"url":"https://parismuseescollections.paris.fr/fr/musee-carnavalet/oeuvres/reconstruction-du-pont-d-austerlitz-novembre-1854"}],"precisionLabel":{"en":"Historic crossing · rebuilt bridge","he":"מעבר היסטורי · הגשר נבנה מחדש"},"photo":{"src":"/assets/places/pont-austerlitz.webp","sourceUrl":"https://commons.wikimedia.org/wiki/File:P1210920_Paris_V-XII-XIII_pont_Austerlitz_rwk.jpg","author":"Mbzt","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0/","title":"P1210920 Paris V-XII-XIII pont Austerlitz rwk.jpg","caption":{"en":"Pont d’Austerlitz in 2013. The present stone bridge postdates the novel’s setting.","he":"גשר אוסטרליץ בשנת 2013. גשר האבן הנוכחי מאוחר לתקופת העלילה."},"alt":{"en":"An oblique view of the stone arches and roadway of Pont d’Austerlitz across the Seine.","he":"מבט אלכסוני על קשתות האבן והכביש של פון ד׳אוסטרליץ מעל הסן."},"width":1600,"height":1200,"modified":true,"transformations":{"he":"הפריים המלא נשמר. התמונה הוקטנה והומרה ל־WebP; ללא חיתוך, צביעה או עריכת התוכן.","en":"Whole frame retained; resized and converted to WebP for web delivery. No content editing, colorization, reconstruction, retouching, or cropping."}}},{"id":"montfermeil","name":{"en":"Montfermeil","he":"מונפרמיי"},"shortIntro":{"en":"A town above a forest spring.","he":"עיירה מעל מעיין ביער."},"region":{"en":"Île-de-France · east of Paris","he":"איל־דה־פראנס · ממזרח לפריז"},"status":"changed-landscape","statusLabel":{"en":"Real town · transformed landscape","he":"עיירה אמיתית · הנוף השתנה"},"coordinates":[48.9,2.566667],"coordinatePrecision":"town-scale reference point; not the inn, spring or meeting site","coordinateSource":"https://fr.wikipedia.org/wiki/Montfermeil","mapNote":{"he":"הסמן מציין את מונפרמיי בקנה מידה של עיר; תצלום בית העירייה מראה אותה כיום.","en":"The pin marks Montfermeil at town scale; the town-hall photograph shows the town today."},"legacyMapId":"montfermeil","novelPart":2,"spoilerLevel":"plot","history":{"en":"Hugo introduces Montfermeil through topography and a practical shortage: a village on a plateau needs water brought uphill. The town east of Paris has changed greatly since the novel’s rural setting. Its municipal history records how a local spring became known as the Fontaine Jean-Valjean after the novel’s success, followed by later restoration and redesign. The story left its mark on local place names. The town-hall photograph shows Montfermeil today, while the forest view brings us back to the surrounding landscape in which Hugo imagines Cosette’s journey.","he":"הוגו מציג את מונפרמיי באמצעות הטופוגרפיה ומחסור מעשי: יישוב על רמה זקוק למים שמביאים אליו במעלה הדרך. העיר שממזרח לפריז השתנתה מאוד מאז הנוף הכפרי של הרומן. ההיסטוריה העירונית מתעדת כיצד מעיין מקומי קיבל את השם ״מזרקת ז׳אן ולז׳אן״ בעקבות הצלחת הספר, ובהמשך שוקם ועוצב מחדש. הסיפור הותיר כך חותם בשמות המקומיים. תצלום בית העירייה מציב אותנו בעיר של ימינו, ומבט היער הנוסף מחזיר אל הנוף האזורי שבתוכו הוגו מדמיין את הליכתה של קוזט."},"novel":{"en":"Madame Thénardier sends Cosette to the forest spring after dark. The eight-year-old has to stop repeatedly on the return climb and set down the bucket. A stranger takes the handle before he asks her name. Once relieved of the load, she can keep up with him; only then does their conversation uncover where she lives and who sent her out. Hugo gives the rescue this order: first the heavy bucket changes hands, then the stranger learns that the child is Cosette.","he":"מאדאם תנרדייה שולחת את קוזט למעיין שביער אחרי רדת החשכה. הילדה בת השמונה נאלצת לעצור שוב ושוב בעלייה בחזרה ולהניח את הדלי. זר אוחז בידית עוד לפני שהוא שואל לשמה. כשהמשא יורד ממנה היא מצליחה לעמוד בקצב הליכתו; רק אז השיחה מגלה היכן היא גרה ומי שלחה אותה החוצה. הוגו בונה כך את ההצלה: תחילה הדלי הכבד עובר לידיים אחרות, ורק אחר כך הזר לומד שהילדה היא קוזט."},"novelRefs":[{"label":{"en":"II · III · 1","he":"חלק II · ספר III · פרק 1"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2HCH0093"},{"label":{"en":"II · III · 5–7","he":"חלק II · ספר III · פרקים 5–7"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2HCH0097"}],"historySources":[{"label":{"en":"Ville de Montfermeil · Fontaine Jean-Valjean","he":"עיריית מונפרמיי · מזרקת ז׳אן ולז׳אן"},"url":"https://www.ville-montfermeil.fr/fontaine-jean-valjean/"}],"precisionLabel":{"en":"Real town · transformed landscape","he":"עיירה אמיתית · הנוף השתנה"},"photo":{"src":"/assets/places/montfermeil-town.webp","sourceUrl":"https://commons.wikimedia.org/wiki/File:H%C3%B4tel_Ville_-_Montfermeil_(FR93)_-_2022-10-23_-_2.jpg","author":"Chabe01","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","title":"Hôtel Ville - Montfermeil (FR93) - 2022-10-23 - 2.jpg","caption":{"en":"Montfermeil’s town hall in October 2022: the novel’s town today.","he":"בית העירייה של מונפרמיי באוקטובר 2022: העיירה מן הרומן, כפי שהיא כיום."},"alt":{"en":"The pale façade of Montfermeil town hall, with French flags, a central entrance and planted beds beneath a cloudy blue sky.","he":"חזיתו הבהירה של בית העירייה במונפרמיי, דגלי צרפת, כניסה מרכזית וערוגות תחת שמיים כחולים מעוננים."},"width":1600,"height":1200,"modified":true,"transformations":{"he":"הפריים המלא נשמר. התמונה הוקטנה והומרה ל־WebP; ללא חיתוך, צביעה או עריכת התוכן.","en":"Whole frame retained; resized and converted to WebP for web delivery. No content editing, colorization, reconstruction, retouching, or cropping."}},"secondaryPhoto":{"src":"/assets/places/montfermeil.webp","sourceUrl":"https://commons.wikimedia.org/wiki/File:For%C3%AAt_R%C3%A9gionale_Bondy_-_Clichy-sous-Bois_(FR93)_-_2020-12-12_-_8.jpg","author":"Chabe01","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","title":"Forêt Régionale Bondy - Clichy-sous-Bois (FR93) - 2020-12-12 - 8.jpg","caption":{"en":"Bondy Forest in 2020, photographed in Clichy-sous-Bois, next to Montfermeil.","he":"יער בונדי בשנת 2020, מצולם בקלישי־סו־בואה השכנה למונפרמיי."},"alt":{"en":"A curving woodland path beneath tall trees and late-autumn leaves in Bondy Forest.","he":"שביל מתעקל ביער בונדי, בין עצים גבוהים ועלי סוף הסתיו."},"width":1280,"height":960,"modified":true,"transformations":{"he":"הפריים המלא נשמר. התמונה הוקטנה והומרה ל־WebP; ללא חיתוך, צביעה או עריכת התוכן.","en":"Whole frame retained; resized and converted to WebP for web delivery. No content editing, colorization, reconstruction, retouching, or cropping."}}},{"id":"sewers","name":{"en":"The Paris sewers","he":"הביוב של פריז"},"shortIntro":{"en":"The sewer network before and after Belgrand.","he":"רשת הביוב לפני בלגראן ואחריו."},"region":{"en":"Paris · citywide underground network","he":"פריז · רשת תת־קרקעית עירונית"},"status":"network-interpretation","statusLabel":{"en":"Historic network · modern reference point","he":"רשת היסטורית · נקודת התמצאות עכשווית"},"coordinates":[48.862642,2.302235],"coordinatePrecision":"modern Musée des Égouts reference point; not the fictional route or exit","coordinateSource":"https://fr.wikipedia.org/wiki/Mus%C3%A9e_des_%C3%89gouts_%28Paris%29","mapNote":{"en":"The pin marks the modern sewer museum, a starting point for exploring the network beneath Paris. The photograph dates to 1897.","he":"הסמן מציין את מוזיאון הביוב העכשווי, נקודת מוצא להיכרות עם הרשת שמתחת לפריז. התצלום מ־1897."},"legacyMapId":null,"novelPart":5,"spoilerLevel":"major","history":{"en":"The municipal sewer museum traces Paris’s drainage system through the nineteenth-century expansion associated with engineer Eugène Belgrand. Albert Brichaut’s photograph dates from 1897, sixty-five years after the novel’s June 1832 action. The map marks the modern museum near Pont de l’Alma, where visitors can learn about the network’s history and operation. It serves as a present-day reference point for the underground passages Hugo describes.","he":"מוזיאון הביוב העירוני עוקב אחר מערכת הניקוז של פריז והרחבתה במאה התשע־עשרה, המזוהה עם המהנדס אז׳ן בלגראן. התצלום של אלבר ברישו הוא מ־1897, שישים וחמש שנים אחרי אירועי יוני 1832 ברומן. המפה מסמנת את המוזיאון העכשווי ליד גשר אלמה, שבו אפשר ללמוד על תולדות הרשת ועל פעולתה. זו נקודת התמצאות בת זמננו למעברים התת־קרקעיים שהוגו מתאר."},"novel":{"en":"After a whole book on the sewers, Hugo returns to Valjean carrying the wounded Marius beneath Paris. At first Valjean works by touch, feeling the walls and testing the wet paving with his feet. The slope offers a clue to the river, but following it could bring him out among police and crowds. He must choose a route while supporting a man who cannot help him. The chapter makes navigation part of the rescue: every junction requires a decision, and neither darkness nor distance guarantees safety.","he":"אחרי ספר שלם על הביוב, הוגו חוזר לוולז׳אן הנושא את מריוס הפצוע מתחת לפריז. בתחילה ולז׳אן מתקדם במישוש, נוגע בקירות ובודק ברגליו את הריצוף הרטוב. השיפוע מסמן את הדרך לנהר, אבל הליכה בעקבותיו עלולה להוציא אותו אל שוטרים והמון. עליו לבחור מסלול בעודו נושא אדם שאינו יכול לעזור לו. הפרק הופך את הניווט לחלק מן ההצלה: כל צומת מחייב החלטה, והחושך והמרחק אינם מבטיחים ביטחון."},"novelRefs":[{"label":{"en":"V · II · 1–6","he":"חלק V · ספר II · פרקים 1–6"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2H_4_0372"},{"label":{"en":"V · III · 1","he":"חלק V · ספר III · פרק 1"},"url":"https://www.gutenberg.org/files/135/135-h/135-h.htm#link2HCH0329"}],"historySources":[{"label":{"en":"Musée des Égouts · History of the Paris sewers","he":"מוזיאון הביוב · תולדות הביוב של פריז"},"url":"https://musee-egouts.paris.fr/les-egouts-lieu-dhistoire/histoire-des-egouts-de-paris/"},{"label":{"en":"Ville de Paris · Sewer museum","he":"עיריית פריז · מוזיאון הביוב"},"url":"https://www.paris.fr/lieux/musee-des-egouts-de-paris-5059"}],"precisionLabel":{"en":"Historic network · modern reference point","he":"רשת היסטורית · נקודת התמצאות עכשווית"},"photo":{"src":"/assets/places/sewers.webp","sourceUrl":"https://commons.wikimedia.org/wiki/File:Les_%C3%A9gouts_de_Paris_(1897)%2C_PH37307_(1_of_2).jpg","author":"Albert Brichaut","license":"CC0 1.0","licenseUrl":"https://creativecommons.org/publicdomain/zero/1.0/","title":"Les égouts de Paris (1897), PH37307 (1 of 2).jpg","caption":{"en":"Paris sewers photographed by Albert Brichaut in 1897, 65 years after the novel’s June 1832 events.","he":"תעלות הביוב של פריז בתצלום של אלבר ברישו משנת 1897, 65 שנה אחרי אירועי יוני 1832 ברומן."},"alt":{"en":"A mounted sepia photograph showing men, pipes and cables inside a Paris sewer tunnel.","he":"תצלום חום־צהבהב על קרטון, ובו אנשים, צינורות וכבלים בתוך תעלת ביוב פריזאית."},"width":1517,"height":2000,"modified":true,"transformations":{"he":"הפריים המלא נשמר. התמונה הוקטנה והומרה ל־WebP; ללא חיתוך, צביעה או עריכת התוכן.","en":"Whole frame retained; resized and converted to WebP for web delivery. No content editing, colorization, reconstruction, retouching, or cropping."}}}]};
